#include <string>
#include <algorithm>

class Solution {
public:
    int minOpsRotatedPalindrome(std::string s) {
        int n = s.size();
        int best = n;
        for (int shift = 0; shift < n; ++shift) {
            std::string rot = s.substr(shift) + s.substr(0, shift);
            int diffs = 0;
            for (int i = 0; i < n / 2; ++i) {
                if (rot[i] != rot[n - 1 - i]) diffs++;
            }
            best = std::min(best, diffs);
        }
        return best;
    }
};

class Solution {
    public int minOpsRotatedPalindrome(String s) {
        int n = s.length();
        int best = n;
        for (int shift = 0; shift < n; shift++) {
            String rot = s.substring(shift) + s.substring(0, shift);
            int diffs = 0;
            for (int i = 0; i < n / 2; i++) {
                if (rot.charAt(i) != rot.charAt(n - 1 - i)) diffs++;
            }
            best = Math.min(best, diffs);
        }
        return best;
    }
}

